  parts: STARTER.parts.map((part) => (part.type === 2001 ? { ...part, type: 4001 } : part)),
};
function shot(world: World, x: number, y: number, enemy = true): Projectile {
  return {
    uid: world.nextId(),
    owner: -1,
    enemy,
    x,
    y,
    angle: 90,
    heading: 90,
    speed: 1,
    damage: 2,
    radius: 2,
    kind: 'shell',
    age: 0,
    life: 500,
    explode: 0,
    hit: new Set(),
    targetId: null,
    dead: false,
    symbol: 0,
    orbit: 0,
  };
}
function cross(world: World) {
